<?php declare(strict_types = 1);

/**
 * Matches every pattern of a set with the engine and checks that the type
 * a PHPStan checkout infers accepts what the engine writes.
 *
 * Usage: php poc/bin/measure.php <phpstan-checkout> <poc/data/set.json.gz> <out-dir>
 *
 * The checkout is either this branch (PHPRegex) or an upstream 2.3.x
 * checkout (the parser generated by phplrt). Writes, in <out-dir>:
 *  - <set>.<side>.types.jsonl: the type inferred for each pattern and call,
 *  - <set>.<side>.refusals.jsonl: each engine result the type does not accept,
 *    with the key it fails on and why,
 *  - <set>.<side>.stats.json.
 *
 * Calls measured, each with every flag combination: preg_match(),
 * preg_match_all() (matched, and maybe matched), and the subject preg_match()
 * narrows. The pcre.jit setting is turned off so a JIT bug of the running
 * PCRE2 cannot crash the run.
 */

[$self, $root, $setFile, $outDir] = $argv + [null, null, null, null];
if ($root === null || $setFile === null || $outDir === null) {
	fwrite(STDERR, "usage: php poc/bin/measure.php <phpstan-checkout> <set.json.gz> <out-dir>\n");
	exit(2);
}

require $root . '/vendor/autoload.php';

use PHPStan\Testing\PHPStanTestCase;
use PHPStan\TrinaryLogic;
use PHPStan\Type\Constant\ConstantIntegerType;
use PHPStan\Type\Constant\ConstantStringType;
use PHPStan\Type\ConstantTypeHelper;
use PHPStan\Type\Php\RegexArrayShapeMatcher;
use PHPStan\Type\Regex\RegexGroupParser;
use PHPStan\Type\Type;
use PHPStan\Type\VerbosityLevel;

final class PocContainer extends PHPStanTestCase
{

	public static function get(string $class): object
	{
		return self::getContainer()->getByType($class);
	}

}

ini_set('pcre.jit', '0');

$side = class_exists('PHPStan\Type\Regex\PHPRegexReader') ? 'phpregex' : 'phplrt';
$set = basename($setFile, '.json.gz');
$rows = json_decode((string) file_get_contents('compress.zlib://' . $setFile), true);
@mkdir($outDir, 0777, true);

/** @var RegexArrayShapeMatcher $matcher */
$matcher = PocContainer::get(RegexArrayShapeMatcher::class);
/** @var RegexGroupParser $groupParser */
$groupParser = PocContainer::get(RegexGroupParser::class);
$matchPatternType = new ReflectionMethod($matcher, 'matchPatternType');

$O = PREG_OFFSET_CAPTURE;
$N = PREG_UNMATCHED_AS_NULL;
$P = PREG_PATTERN_ORDER;
$S = PREG_SET_ORDER;
$calls = [
	['match', null], ['match', $O], ['match', $N], ['match', $O | $N],
	['all', null], ['all', $S], ['all', $P | $O], ['all', $S | $O], ['all', $P | $N], ['all', $S | $N], ['all', $P | $O | $N], ['all', $S | $O | $N],
	['allmaybe', null], ['allmaybe', $S], ['allmaybe', $S | $O | $N], ['allmaybe', $P | $O | $N],
];

/**
 * A type as PHPStan prints it, with the bytes past UTF-8 a class without u
 * reads written \xHH, so the JSON keeps them.
 */
function poc_describe(?Type $type): ?string
{
	if ($type === null) {
		return null;
	}
	$text = $type->describe(VerbosityLevel::precise());

	return mb_check_encoding($text, 'UTF-8') ? $text : (string) preg_replace_callback('/[\x80-\xff]/', static fn (array $byte): string => sprintf('\\x%02x', ord($byte[0])), $text);
}

$json = static fn (array $row): string => json_encode($row, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n";
$types = fopen("$outDir/$set.$side.types.jsonl", 'w');
$refusals = fopen("$outDir/$set.$side.refusals.jsonl", 'w');
$stats = ['patterns' => 0, 'shapes' => 0, 'noShape' => 0, 'checks' => 0, 'refusals' => 0];

/**
 * Why the type does not accept the engine result: the first key of the
 * closest array of the type that fails, and how.
 *
 * @param array<mixed> $value
 * @return array{key: int|string|null, reason: string}
 */
function poc_reason(Type $type, array $value): array
{
	$best = null;
	foreach ($type->getConstantArrays() as $shape) {
		$issues = [];
		foreach ($value as $key => $item) {
			$keyType = is_int($key) ? new ConstantIntegerType($key) : new ConstantStringType($key);
			if ($shape->hasOffsetValueType($keyType)->no()) {
				$issues[] = ['key' => $key, 'reason' => 'absent'];
				continue;
			}
			$itemType = $shape->getOffsetValueType($keyType);
			if (!$itemType->isSuperTypeOf(ConstantTypeHelper::getTypeFromValue($item))->yes()) {
				$issues[] = ['key' => $key, 'reason' => poc_holds_falsy($item) && !$itemType->isSuperTypeOf(new ConstantStringType('0'))->yes() ? 'falsy' : 'value'];
			}
		}
		foreach ($shape->getKeyTypes() as $i => $keyType) {
			$key = $keyType->getValue();
			if (!array_key_exists($key, $value) && !in_array($i, $shape->getOptionalKeys(), true)) {
				$issues[] = ['key' => $key, 'reason' => 'present'];
			}
		}
		if ($issues !== [] && ($best === null || count($issues) < count($best))) {
			$best = $issues;
		}
	}

	return $best[0] ?? ['key' => null, 'reason' => 'value'];
}

/**
 * Whether a value written for a key holds '0' or '', where a falsy
 * string typed non-falsy or non-empty is the commonest refusal.
 */
function poc_holds_falsy(mixed $item): bool
{
	if (is_array($item)) {
		foreach ($item as $part) {
			if (poc_holds_falsy($part)) {
				return true;
			}
		}

		return false;
	}

	return $item === '0' || $item === '';
}

foreach ($rows as $row) {
	$pattern = $row['pattern'];
	if (@preg_match($pattern, '') === false) {
		continue;
	}
	$stats['patterns']++;
	$subjects = array_map('base64_decode', $row['subjects']);

	$walk = $groupParser->parseGroups($pattern);
	$narrow = $walk === null ? null : ($side === 'phpregex' ? $walk->getSubjectNarrowType() : $walk->getSubjectBaseType());
	fwrite($types, $json(['p' => $pattern, 'c' => 'subject', 't' => poc_describe($narrow)]));
	if ($narrow !== null) {
		foreach ($subjects as $subject) {
			if (@preg_match($pattern, $subject) !== 1) {
				continue;
			}
			$stats['checks']++;
			if (!$narrow->isSuperTypeOf(new ConstantStringType($subject))->yes()) {
				$stats['refusals']++;
				fwrite($refusals, $json(['p' => $pattern, 'c' => 'subject', 's' => base64_encode($subject), 'e' => base64_encode(serialize($subject)), 't' => poc_describe($narrow), 'key' => null, 'reason' => 'subject']));
			}
		}
	}

	foreach ($calls as [$call, $flags]) {
		$all = $call !== 'match';
		$type = $matchPatternType->invoke($matcher, new ConstantStringType($pattern), $flags === null ? null : new ConstantIntegerType($flags), $call === 'allmaybe' ? TrinaryLogic::createMaybe() : TrinaryLogic::createYes(), $all);
		$label = $call . ':' . ($flags ?? 'null');
		fwrite($types, $json(['p' => $pattern, 'c' => $label, 't' => poc_describe($type)]));
		if ($type === null) {
			$stats['noShape']++;
			continue;
		}
		$stats['shapes']++;
		$seen = [];
		foreach ($subjects as $subject) {
			$matches = [];
			$result = $all ? @preg_match_all($pattern, $subject, $matches, $flags ?? $P) : @preg_match($pattern, $subject, $matches, $flags ?? 0);
			if ($result === false || ($call !== 'allmaybe' && $result === 0)) {
				continue;
			}
			$key = serialize($matches);
			if (isset($seen[$key])) {
				continue;
			}
			$seen[$key] = true;
			$stats['checks']++;
			if ($type->isSuperTypeOf(ConstantTypeHelper::getTypeFromValue($matches))->no()) {
				$stats['refusals']++;
				fwrite($refusals, $json(['p' => $pattern, 'c' => $label, 's' => base64_encode($subject), 'e' => base64_encode($key), 't' => poc_describe($type)] + poc_reason($type, $matches)));
			}
		}
	}
}

file_put_contents("$outDir/$set.$side.stats.json", json_encode($stats, JSON_PRETTY_PRINT) . "\n");
fwrite(STDERR, "$set $side " . json_encode($stats) . "\n");
